#include <concepts>
#include <cstddef>
#include <iostream>
#include <vector>

template<class T>
std::size_t itemCount(const T& value)
{
    if constexpr (requires { { value.size() } -> std::convertible_to<std::size_t>; })
        return static_cast<std::size_t>(value.size());
    else
    {
        static_assert(std::same_as<T, std::size_t>);
        return value;
    }
}

int main()
{
    const std::vector<int> chapters{2, 4, 6};
    std::cout << itemCount(chapters) << ' '
              << itemCount(std::size_t{7}) << '\n';
}
